<?php require __DIR__.'/../app/bootstrap.php';require __DIR__.'/_layout.php';$u=require_admin();$msg='';$err='';$keys=['company_name','support_email','billing_email','invoice_prefix','currency','vat_rate','invoice_due_days','renewal_days_before','grace_days','auto_suspend','auto_unsuspend','smtp_host','smtp_port','smtp_security','smtp_username','smtp_password','smtp_from_email','smtp_from_name','cron_token','mail_provider','m365_tenant_id','m365_client_id','m365_sender_email'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{foreach($keys as $k)if(array_key_exists($k,$_POST))save_setting($k,(string)$_POST[$k]); if(isset($_POST['m365_client_secret']) && trim((string)$_POST['m365_client_secret'])!=='') save_setting('m365_client_secret','enc:'.enc(trim((string)$_POST['m365_client_secret']))); $msg='Settings saved.';}catch(Throwable $e){$err=$e->getMessage();}}admin_head($u,'Settings','settings');?><?php if($msg):?><div class="notice"><?=e($msg)?></div><?php endif?><?php if($err):?><div class="error"><?=e($err)?></div><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><section class="card settings-card"><div class="cardhead"><b>COMPANY & BILLING</b></div><div class="admin-form-grid"><?php foreach(['company_name'=>'Company name','support_email'=>'Support email','billing_email'=>'Billing email','invoice_prefix'=>'Invoice prefix','currency'=>'Currency','vat_rate'=>'VAT rate (%)','invoice_due_days'=>'Invoice due days','renewal_days_before'=>'Create renewal invoice days before due','grace_days'=>'Grace days before suspension'] as $k=>$l):?><label><?=$l?><input name="<?=$k?>" value="<?=e(setting($k,''))?>"></label><?php endforeach?><label>Automatic suspension<select name="auto_suspend"><option value="1" <?=setting('auto_suspend','1')==='1'?'selected':''?>>Enabled</option><option value="0" <?=setting('auto_suspend','1')==='0'?'selected':''?>>Disabled</option></select></label><label>Automatic unsuspension<select name="auto_unsuspend"><option value="1" <?=setting('auto_unsuspend','1')==='1'?'selected':''?>>Enabled</option><option value="0" <?=setting('auto_unsuspend','1')==='0'?'selected':''?>>Disabled</option></select></label></div></section><section class="card settings-card"><div class="cardhead"><b>EMAIL PROVIDER</b></div><div class="admin-form-grid"><label>Email provider<select name="mail_provider"><option value="m365" <?=setting('mail_provider','smtp')==='m365'?'selected':''?>>Microsoft 365 / Graph</option><option value="smtp" <?=setting('mail_provider','smtp')==='smtp'?'selected':''?>>SMTP</option></select></label></div></section><section class="card settings-card"><div class="cardhead"><b>MICROSOFT 365 / GRAPH</b><span class="muted">Recommended for FoxNetwork business mail</span></div><div class="admin-form-grid"><label>Tenant ID<input name="m365_tenant_id" value="<?=e(setting('m365_tenant_id',''))?>" placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"></label><label>Client ID<input name="m365_client_id" value="<?=e(setting('m365_client_id',''))?>" placeholder="Application (client) ID"></label><label>Client secret<input type="password" name="m365_client_secret" value="" placeholder="Leave blank to keep saved secret"></label><label>Sender mailbox<input type="email" name="m365_sender_email" value="<?=e(setting('m365_sender_email',''))?>" placeholder="noreply@foxnetwork.be"></label></div><p class="muted" style="margin-top:12px">Azure app requires Microsoft Graph <b>Mail.Send</b> application permission with admin consent. The client secret is encrypted before it is stored.</p></section><section class="card settings-card"><div class="cardhead"><b>SMTP EMAIL</b></div><div class="admin-form-grid"><?php foreach(['smtp_host'=>'SMTP host','smtp_port'=>'SMTP port','smtp_username'=>'SMTP username','smtp_password'=>'SMTP password','smtp_from_email'=>'From email','smtp_from_name'=>'From name'] as $k=>$l):?><label><?=$l?><input <?=$k==='smtp_password'?'type="password"':''?> name="<?=$k?>" value="<?=e(setting($k,''))?>"></label><?php endforeach?><label>Security<select name="smtp_security"><option value="tls" <?=setting('smtp_security')==='tls'?'selected':''?>>STARTTLS</option><option value="ssl" <?=setting('smtp_security')==='ssl'?'selected':''?>>SSL/TLS</option><option value="none" <?=setting('smtp_security')==='none'?'selected':''?>>None</option></select></label><label>Cron token<input name="cron_token" value="<?=e(setting('cron_token',''))?>"></label></div></section><button class="btn primary" style="margin-top:16px">Save settings</button></form><?php admin_foot(); ?>
